<?php
declare(strict_types=1);require_once __DIR__.'/seo.php';header('Content-Type: application/xml; charset=utf-8');$urls=[['loc'=>seo_url(),'lastmod'=>date('Y-m-d'),'priority'=>'1.0'],['loc'=>seo_url('plot-finder.html'),'lastmod'=>date('Y-m-d'),'priority'=>'0.8'],['loc'=>seo_url('installment-calculator.html'),'lastmod'=>date('Y-m-d'),'priority'=>'0.8']];try{$pdo=seo_db();seo_ensure_schema($pdo);foreach($pdo->query("SELECT slug,updated_at FROM properties WHERE status='available' AND (publish_start_date IS NULL OR publish_start_date<=CURRENT_DATE) AND (publish_end_date IS NULL OR publish_end_date>=CURRENT_DATE)")->fetchAll() as $row)$urls[]=['loc'=>seo_url('property/'.$row['slug']),'lastmod'=>substr($row['updated_at'],0,10),'priority'=>'0.9'];foreach($pdo->query("SELECT slug,location,updated_at FROM projects WHERE status='published'")->fetchAll() as $row){$urls[]=['loc'=>seo_url('project/'.$row['slug']),'lastmod'=>substr($row['updated_at'],0,10),'priority'=>'0.9'];$urls[]=['loc'=>seo_url('location/'.seo_slugify($row['location'])),'lastmod'=>substr($row['updated_at'],0,10),'priority'=>'0.7'];}foreach($pdo->query("SELECT DISTINCT city FROM properties WHERE status='available'")->fetchAll() as $row)$urls[]=['loc'=>seo_url('location/'.seo_slugify($row['city'])),'lastmod'=>date('Y-m-d'),'priority'=>'0.7'];}catch(Throwable $e){}$unique=[];foreach($urls as $url)$unique[$url['loc']]=$url;echo '<?xml version="1.0" encoding="UTF-8"?>'."\n".'<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';foreach($unique as $url)echo '<url><loc>'.htmlspecialchars($url['loc'],ENT_XML1|ENT_QUOTES,'UTF-8').'</loc><lastmod>'.$url['lastmod'].'</lastmod><changefreq>weekly</changefreq><priority>'.$url['priority'].'</priority></url>';echo '</urlset>';
